import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.yo2CxoV2.js";const c=JSON.parse('{"title":"PWA、离线画布与业务快照","description":"","frontmatter":{},"headers":[],"relativePath":"guides/offline.md","filePath":"guides/offline.md","lastUpdated":1794339637000}'),n={name:"guides/offline.md"};function l(o,s,p,h,d,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="pwa、离线画布与业务快照" tabindex="-1">PWA、离线画布与业务快照 <a class="header-anchor" href="#pwa、离线画布与业务快照" aria-label="Permalink to &quot;PWA、离线画布与业务快照&quot;">​</a></h1><p>离线程序、画布编辑与只读业务快照分别配置。业务快照采用导出副本语义，需要由使用者主动保存。</p><h2 id="pwa-与诊断命令" tabindex="-1">PWA 与诊断命令 <a class="header-anchor" href="#pwa-与诊断命令" aria-label="Permalink to &quot;PWA 与诊断命令&quot;">​</a></h2><p>数据层、事件和表单的双进程并发验证见仓库的 <a href="https://github.com/neekin/simpleui-antd/blob/main/docs/capacity.md" target="_blank" rel="noreferrer">容量验证方法与基线</a>。 包含 PostgreSQL/SQLite、真实 Redis、权限撤销、推送、限流及数值精度探针；需要单独的验证依赖和 Docker， 只创建自己的临时资源，不连接宿主已有数据库。结果不是生产容量承诺。</p><p>消息中心与审计留存的配置也纳入诊断；完整说明见下文。</p><ul><li><code>GET /api/manifest.webmanifest/</code>：动态 PWA 安装清单，<code>name</code>/<code>short_name</code> 取自站点标题，<code>start_url</code>/<code>scope</code> 为当前挂载点，图标指向包内 <code>static/ordloom/icons/</code>。工作台入口页自动注入 <code>&lt;link rel=&quot;manifest&quot;&gt;</code> 与 <code>theme-color</code>；公开分享页不注入。离线画布单独启用，见下文。</li><li><code>python manage.py ordloom_check [--json]</code>：配置诊断，覆盖应用注册、URL 挂载、 迁移状态（未应用时提示执行 <code>migrate</code>）、前端构建产物、可选 GraphQL 依赖（启用但不可用时判定失败）、 站点配置与可视化数据概况；<code>--json</code> 输出机器可读结果，存在失败项时退出码为 1，可直接用于部署脚本。</li></ul><h3 id="离线画布与联网另存" tabindex="-1">离线画布与联网另存 <a class="header-anchor" href="#离线画布与联网另存" aria-label="Permalink to &quot;离线画布与联网另存&quot;">​</a></h3><p>默认关闭。执行迁移及 <code>collectstatic</code> 后，在宿主配置：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ORDLOOM_PWA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;offline&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>使用 HTTPS 或 localhost，并从同源地址提供静态资源。在「页面搭建 → 本机画布与离线准备」点击 「准备或更新离线资源」，等待成功后打开「本机画布」。断网时可继续从 <code>&lt;挂载点&gt;/offline/</code> 打开， 也可在管理页面导航网络失败后进入通用画布；新建模板、导入 JSON、编辑排版、预览、保存本机修订及导出均可使用。 外链图片、音视频和外部链接不在离线预览中加载，包内六张图片及支持的图片 data URI 可使用。</p><p>本机文档保存在此浏览器的 IndexedDB，按域名和挂载点隔离，<strong>不随登录账号隔离</strong>；界面明确提示其类似本机 JSON 文件。 不会自动下载私有页面或业务结果。每挂载点最多 20 份文档，每份 2 MiB、合计 20 MiB；多窗口写入校验修订号， 冲突不覆盖较新内容，当前修改可导出。浏览器可能回收本机存储，重要文档需自行导出备份。</p><p>联网后登录 staff 账号，在上述面板显式选择文档修订「另存为新页面」。<code>POST /api/offline/import/</code> 使用当前 Session/CSRF 和账号权限，创建本人新页面，默认关闭公开分享；不覆盖已有页面。相同账号、文档编号与修订重试返回原页面， 不会重放内容覆盖后续在线编辑；原目标已删除或不再属于本人时返回冲突，另一个账号可显式另存自己的副本。 本机导入和联网另存均清除数据集/报表业务引用及页面数据授权，表单停止收集；联网后需重新绑定发布版本、字段与实参。</p><p>程序使用 <code>&lt;挂载点&gt;/ordloom-offline-worker.js</code>。同一精确 scope 已有其他 Service Worker 时拒绝准备， 可使用独立挂载点；更上层的宿主 PWA 可以保留。准备仅缓存清单内的包内静态资源及不含账号信息的通用画布入口， 逐项检查 SHA-256 和字节数，失败时保留旧缓存；不缓存管理 HTML、API、数据集查询结果、答卷、上传文件或凭据。 基础画布提供离线页面设计；只读业务导出需额外启用下节快照功能，仍不提供离线授权查询、表单提交队列或自动同步。程序更新遵循默认 Worker 生命周期， 提示更新已准备时关闭本站所有窗口并重新打开；关闭配置后 Worker 下次成功更新只清理自身缓存并注销，不删除本机文档。</p><h3 id="离线业务快照" tabindex="-1">离线业务快照 <a class="header-anchor" href="#离线业务快照" aria-label="Permalink to &quot;离线业务快照&quot;">​</a></h3><p>在已启用 GraphQL 数据层和离线画布的宿主上，可额外启用只读快照，默认关闭：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ORDLOOM_PWA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;offline&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;snapshots&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>无需新增模型或迁移。执行前端构建/<code>collectstatic</code>，使用同源静态资源与 HTTPS/localhost。 页面列表每张大屏/H5 的「业务快照」先显示当前保存页面及可见数据组件数量； 用户确认保存到设备后，准备程序资源，再读取业务数据并保存独立本机副本。 若已有程序更新仍在等待激活，先关闭本站窗口并重新打开，再生成快照，避免旧离线程序无法展示新格式。</p><ul><li><code>GET api/offline/snapshots/&lt;page_id&gt;/</code> 仅读取页面名称、类型、可见数据组件数及当前配置令牌，不执行业务查询。 <code>POST</code> 提交 <code>{&quot;configuration_token&quot;:&quot;&lt;读取到的令牌&gt;&quot;,&quot;acknowledged&quot;:true}</code>；仅接受已有保存页面， 不接受调用者上传查询或页面定义，复用 Session/CSRF、当前页面/数据集/报表的 read 权限与完整业务数据权限。 默认仍按创建人隔离；显式协作的只读使用者也只能导出自己当前有权读取的数据，不借用页面创建人或公开授权身份。</li><li>只处理未隐藏、已绑定的组件：固定数据集发布版本按页面已保存实参执行，报表按生成时最新保存定义和实参执行。 同一数据集版本/实参、同一报表/实参在单次生成中合并查询，整页共用原有 20 次查询预算。 原有归档数据集的已保存引用可继续执行；权限/字段/类型失效、超限或任一组件失败时，整个生成失败，不保存半份快照。</li><li>响应保留布局、采集时间、每个数据组件的映射与映射所需输出值；不包含查询定义、业务实参、 可继续执行的数据集/报表 ID、公开数据授权令牌或未映射输出列。表单停止收集，外链媒体不自动下载。 明细/统计沿用组件配置的第 1 页或分组上限，不遍历全部业务记录；仍有后续结果时展示截断提示。 字符串形式的 BigInt/Decimal 保持精度；图表沿用现有安全数值检查及数据库精度限制。</li><li>页面或引用报表配置在采集过程中变化会拒绝生成；业务查询在一段时间内依次执行， <strong>不承诺跨模型、跨数据库同一时刻的一致性快照</strong>。重新采集创建新副本，不改写旧快照。</li><li>每份最多 2 MiB、本机最多 20 份/合计 20 MiB，快照与可编辑画布使用独立 IndexedDB 库，均按源站及挂载点隔离。 本机画布中的「只读业务快照」可查看、全屏、导入/导出 <code>.snapshot.json</code>、按修订号删除。 数值、表格及 ECharts/AntV 数据复用现有渲染；报表转换为只读图表或表格，不再发起业务 API、轮询或订阅，表单不提交。</li><li><strong>本机副本采用导出文件的访问语义</strong>：当前浏览器使用者可查看/导出，不随在线账号隔离； 断网后无法复核账号权限，也无法撤回已导出数据。生成前界面明确说明并由用户确认，按设备资料管理要求保留或删除。 关闭宿主功能、退出或撤销在线权限不会删除已有本机副本及用户导出的文件。 导入文件由使用者提供、可被编辑，不是服务器签名或审计证据，也不授予任何在线业务权限。</li><li>业务值只在用户主动保存的快照库/文件中，不进入 Service Worker 的程序资源缓存； 管理 HTML、API、在线页面、表单答案和自动后台同步的原有边界不变。服务器不保存快照结果，不修改在线页面。</li></ul><p>开发验证（临时 SQLite/专用临时 PostgreSQL，不连接已有宿主数据库）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test_backend.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ordloom.tests.test_offline_snapshots</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test_offline_snapshots.py</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 可选 PostgreSQL 依赖和归属校验见脚本头部</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test_ownership_postgres.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --snapshots</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frontend：文档、Worker、IndexedDB 模拟事务、快照映射</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:offline-unit</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frontend：快照确认/冲突/程序更新、只读渲染（模拟 API，无 Canvas）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:collaboration-ui</span></span></code></pre></div><p>演示用 <code>scripts/dev_fields.py --snapshots --production</code>，沿用合成业务数据。 2026-11-11 已在本仓库 Django 测试宿主完成真实浏览器断网复验：停止自身服务器后编辑/重载/导出，恢复网络后显式另存；只读业务快照在模拟断网后重载、导入和导出，业务接口仍不可读取。记录见仓库 <a href="https://github.com/neekin/simpleui-antd/blob/main/docs/roadmap-acceptance.md" target="_blank" rel="noreferrer">验收矩阵</a>。移动宽度检查使用桌面浏览器模拟，真机安装与生产接入按部署验收。</p>`,21)])])}const g=i(n,[["render",l]]);export{c as __pageData,g as default};
